// TestInvoiceWithoutLinesAnswers reproduces the incident: an invoice with no lines made the list and the get answer 500,
// because the description indexed the first line. Such an invoice has the description "".
func TestInvoiceWithoutLinesAnswers(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, Currency: money.USD}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	var list struct{ Items []struct{ ID, Description string } }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices", e.Acme.Key, nil, &list)
	if len(list.Items) != 1 || list.Items[0].ID != inv.ID || list.Items[0].Description != "" {
		t.Fatalf("list = %+v", list)
	}
	var got struct{ Description string }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &got)
	if got.Description != "" {
		t.Fatalf("get = %+v", got)
	}
	var paid struct {
		Invoice struct{ Status store.InvoiceStatus }
	}
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+inv.ID+"/pay", e.Acme.Key, nil, &paid)
	if paid.Invoice.Status != store.InvoicePaid {
		t.Fatalf("pay = %+v", paid)
	}
	empty, _ := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, Currency: money.USD}, e.Clock.Now())
	var voided struct{ Status store.InvoiceStatus }
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+empty.ID+"/void", e.Acme.Key, nil, &voided)
	if voided.Status != store.InvoiceVoid {
		t.Fatalf("void = %+v", voided)
	}
}

// TestFreePlanInvoicesAnswer starts a free licensed plan: its invoice has one zero-price line and is paid at once.
func TestFreePlanInvoicesAnswer(t *testing.T) {
	e := apitest.New(t)
