	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID, "quantity": 2}, nil)
	var invs struct {
		Items []struct {
			store.Invoice
			Description string
			Total       int64
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+c.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 {
		t.Fatalf("invoices = %+v", invs)
	}
	inv := invs.Items[0]
	if inv.Status != store.InvoicePaid || inv.Total != 0 || len(inv.Lines) != 1 || inv.Lines[0].Quantity != 2 || inv.Lines[0].UnitAmount != 0 || !strings.HasPrefix(inv.Description, "Free, ") {
		t.Fatalf("invoice = %+v", inv)
	}
}

