243	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
244		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
245			x.Status = st
246			return nil
247		})
248		if err == nil {
249			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
250		}
251		return sub, err
252	}
253	
254	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
255		if s.Publisher != nil {
256			_ = s.Publisher.Publish(ctx, orgID, typ, data)
257		}
258	}
