1	// Package payments charges invoices through the payment gateway.
2	package payments
3	
4	import (
5		"context"
6		"errors"
7		"fmt"
8	
9		"example.com/tally/internal/billing"
10		"example.com/tally/internal/clock"
11		"example.com/tally/internal/money"
12		"example.com/tally/internal/store"
13	)
14	
15	// ChargeRequest asks the gateway to take money from a payment method.
16	type ChargeRequest struct {
17		Amount        int64 // minor units
18		Currency      money.Currency
19		PaymentMethod string // "pm_..."
20		Description   string
21	}
22	
23	// ChargeResult is a successful charge.
24	type ChargeResult struct {
25		Ref string // the gateway's reference, "ch_..."
26	}
27	
28	// Gateway is the payment processor.
29	type Gateway interface {
30		Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
31	}
32	
33	// DeclineError is a charge the card's issuer refused. Nothing was taken.
34	type DeclineError struct {
35		Code string // for example "card_declined", "insufficient_funds"
36	}
37	
38	func (e *DeclineError) Error() string { return "card declined: " + e.Code }
39	
40	// Errors.
41	var (
42		// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
43		ErrUnavailable     = errors.New("payment gateway unavailable")
44		ErrAlreadyPaid     = errors.New("the invoice is already paid")
45		ErrInvoiceVoid     = errors.New("the invoice is void")
46		ErrNoPaymentMethod = errors.New("no payment method to charge")
47	)
48	
49	// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
50	type Publisher interface {
51		Publish(ctx context.Context, orgID, eventType string, data any) error
52	}
53	
54	// Service pays invoices.
55	type Service struct {
56		Store     *store.Store
57		Gateway   Gateway
58		Clock     clock.Clock
59		Publisher Publisher // nil: no events
60	}
61	
62	// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
63	// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
64	// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
65	// error wraps ErrUnavailable.
66	func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
67		inv, ok := s.Store.Invoice(orgID, invoiceID)
68		if !ok {
69			return store.Invoice{}, store.Payment{}, store.ErrNotFound
70		}
71		switch inv.Status {
72		case store.InvoicePaid:
73			return inv, store.Payment{}, ErrAlreadyPaid
74		case store.InvoiceVoid:
75			return inv, store.Payment{}, ErrInvoiceVoid
76		}
77		total := billing.Compute(inv).Total
78		if total <= 0 {
79			inv, err := s.markPaid(ctx, inv, store.Payment{})
80			return inv, store.Payment{}, err
81		}
82		if paymentMethod == "" {
83			if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
84				paymentMethod = c.DefaultPaymentMethod
85			}
86		}
87		if paymentMethod == "" {
88			return inv, store.Payment{}, ErrNoPaymentMethod
89		}
90		res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
91		var decline *DeclineError
92		switch {
93		case errors.As(err, &decline):
94			p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
95			if perr != nil {
96				return inv, store.Payment{}, perr
97			}
98			s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
99			return inv, p, err
100		case err != nil:
101			if errors.Is(err, ErrUnavailable) {
102				return inv, store.Payment{}, err
103			}
104			return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
105		}
106		p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
107		if err != nil {
108			return inv, store.Payment{}, err
109		}
110		inv, err = s.markPaid(ctx, inv, p)
111		return inv, p, err
112	}
113	
114	func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
115		now := s.Clock.Now()
116		inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
117			i.Status = store.InvoicePaid
118			i.PaidAt = &now
119			return nil
120		})
121		if err != nil {
122			return store.Invoice{}, err
123		}
124		s.publish(ctx, inv.OrgID, "invoice.paid", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "amount": p.Amount, "currency": inv.Currency})
125		return inv, nil
126	}
127	
128	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
129		if s.Publisher != nil {
130			_ = s.Publisher.Publish(ctx, orgID, typ, data)
131		}
132	}
