77		}
78		q := r.URL.Query()
79		status := store.InvoiceStatus(q.Get("status"))
80		if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
81			writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
82			return
83		}
84		invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
