154	// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
155	func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
156		var in struct {
157			PaymentMethod string `json:"payment_method"`
158		}
159		if r.ContentLength != 0 && !decode(w, r, &in) {
160			return
161		}
162		inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
163		if err != nil {
164			s.payError(w, err)
165			return
166		}
167		writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
168	}
