170	func (s *Server) payError(w http.ResponseWriter, err error) {
171		var decline *payments.DeclineError
172		switch {
173		case errors.As(err, &decline):
174			writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
175		case errors.Is(err, payments.ErrAlreadyPaid):
176			writeError(w, http.StatusConflict, "already_paid", err.Error())
177		case errors.Is(err, payments.ErrInvoiceVoid):
178			writeError(w, http.StatusConflict, "invoice_void", err.Error())
179		case errors.Is(err, payments.ErrNoPaymentMethod):
180			writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
181		case errors.Is(err, payments.ErrUnavailable):
182			writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
183		default:
184			s.storeError(w, err)
185		}
186	}
